# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
L=[['拉丁 levis → levare','轻 → 抬起、使负担减轻']]
R=L+[['拉丁 re- + levare → relevare','抬起、使脱离负担'],['古法语 relever → 英语 relieve','援助、缓解、解除职责']]
AL=L+[['晚期拉丁 ad- + leviare → alleviare，分词 alleviatus','使变轻、减轻'],['英语 alleviate','减轻痛苦、压力或困难']]
RE=L+[['拉丁 relevare → 中世纪拉丁 relevans','减轻负担、帮助 → 有帮助的'],['法语 relevant → 英语 relevant','与当前事情相联、适用的']]
def A(h,a,b):return h+[[a,b]]
WA=[
E('relieve','/rɪˈliːv/','缓解；使放心；接替；解除','把压在肩上的东西抬走一点，人就轻松了。','拉丁 re- + levare“抬起、减轻”→ relevare，经法语进入英语；此处 re- 不必硬译成再一次。',R,'relieve pain 是减轻痛苦；relieve someone of a duty 是让某人不再承担那项职责；relieve a guard 还可以是来接班，让对方离岗休息。几种意思都能连到“卸下负担”。','relieve pressure；relieve someone of something；relieve someone on duty。','release 常强调放开、释放；relieve 常强调某种压力、负担或职责减轻。relief 是相应名词，末尾读 /f/。',('The new route helped relieve traffic congestion.','新路线帮助缓解了交通拥堵。'),('Another nurse arrived to relieve her at midnight.','另一名护士午夜来接她的班。'),sources=['https://www.etymonline.com/word/relieve']),
E('relief','/rɪˈliːf/','缓解；宽慰；救济；接替；浮雕、地形起伏','一条线是把重担抬走，另一条线是把形状从平面上凸出来。','缓解义经古法语 relief；浮雕义经意大利 rilievo、法语 relief。两条借入支线都接拉丁 relevare“抬起”。',L+[['拉丁 relevare','抬起、减轻'],['并行支线：古法语 relief → 英语 relief','援助、减轻 → 宽慰、救济'],['另一支线：意大利 rilievo → 法语 relief → 英语 relief','凸起 → 浮雕；地表起伏']],'a sigh of relief 是终于放心后的叹气；disaster relief 是救灾援助。a relief on a wall 则是墙上凸起的雕刻，relief map 表现地表起伏；不要把这些都翻成“缓解”。','with relief；a sense of relief；disaster relief；a relief map。','relieve 是动词，relief 是名词；浮雕义有自己的借入路线，并非现代英语临时把“安心”改成雕刻。',('She sighed with relief when the missing bag was found.','遗失的包找到后，她宽慰地松了口气。'),('The relief map shows the mountains and valleys clearly.','地形图清楚显示了山脉和山谷的起伏。'),('The charity sent food and blankets for disaster relief.','慈善机构送去了用于救灾的食物和毯子。'),sources=['https://www.etymonline.com/word/relief']),
E('relieved','/rɪˈliːvd/','放心的；如释重负的；已被接替的','原来悬着的心落下来，肩上的担子终于松了。','relieve + -d。',A(R,'英语 relieved','已经得到缓解；感到轻松或被解除职责'),'feel relieved 常在担心的事没有发生、难题已经解决时使用。be relieved of duty 则说被解除职责，不一定是本人高兴，所以要看后面的搭配。','relieved to hear；relieved that；feel relieved；be relieved of duty。','relaxed 是放松的状态；relieved 常带“先前有担忧、现在担忧减轻”的前后变化。',('I was relieved to hear that everyone had arrived safely.','听说大家都平安到达，我放心了。'),('He looked relieved when the difficult meeting ended.','那场难开的会议结束时，他看起来如释重负。')),
E('relieving','/rɪˈliːvɪŋ/','正在缓解的；令人宽慰的；接替的','重点放在“负担正在被减轻”这个过程或作用上。','relieve 去词尾 e + -ing。',A(R,'英语 relieving','正在缓解；起到缓解、接替作用的'),'relieving pressure 是正在缓解压力；a relieving teacher 在一些地区可指来代课的老师。表达“我松了口气”通常用 I felt relieved，或 That was a relief，更自然。','relieving pressure；relieving congestion；a relieving officer。','relieving 强调带来缓解的动作或作用；relieved 说感到轻松的人，二者不能随意换。',('The extra bus is relieving pressure on the morning service.','加开的公交车正在缓解早班车的压力。'),('She spent the afternoon relieving a colleague at reception.','她下午在前台替同事值班。')),
E('reliever','英 /rɪˈliːvə/；美 /rɪˈliːvər/','缓解物；接替者；救援投手','谁或什么把负担接过去，就可以被称作 reliever。','relieve 去词尾 e + -er。',A(R,'英语 reliever','起缓解、接替作用的人或物'),'a stress reliever 是让人减压的事物；棒球里 a reliever 是接替前一位投手上场的救援投手。它可以指人，也可以指东西，不只表示一种药。','a pain reliever；a stress reliever；a relief pitcher／reliever。','relief 是缓解或救援本身；reliever 是提供缓解、承担接替作用的对象。',('Gardening is a useful stress reliever for her.','园艺对她来说是一种有效的减压活动。'),('The manager brought in a reliever in the seventh inning.','教练在第七局换上了一名救援投手。')),
E('alleviate','/əˈliːvieɪt/','减轻；缓和〔问题、痛苦、压力〕','重担还在，但比刚才轻一些，没那么难扛了。','晚期拉丁 alleviare“使轻”，来自 ad- + leviare；英语借用分词 alleviatus 的词干。',AL,'alleviate a shortage 是缓解短缺，不一定彻底消除短缺；alleviate suffering 是减轻痛苦。常用于较正式的说明，宾语多是负面状态。','alleviate pressure；alleviate suffering；alleviate a shortage。','eliminate 是消除；alleviate 是减轻。alleviate 通常说减轻问题，而不是直接说 alleviate a person。',('The extra staff helped alleviate the workload.','增派的人手帮助减轻了工作负担。'),('The new reservoir may alleviate water shortages in dry months.','新水库可能缓解旱季月份的缺水问题。'),sources=['https://www.etymonline.com/word/alleviate']),
E('alleviation','/əˌliːviˈeɪʃən/','减轻；缓解','把原来沉重或难受的情况变轻一点的过程和结果。','借自中世纪拉丁 alleviatio，来自 alleviare；现代可联系 alleviate 与 -ation，不能把现代拆分当作先后顺序。',L+[['晚期拉丁 alleviare → 中世纪拉丁 alleviatio','减轻 → 减轻这一过程'],['英语 alleviate／alleviation','缓和问题／问题得到缓解']],'poverty alleviation 关注减少贫困带来的困难；pain alleviation 说痛苦减轻。这个词多用于正式文本，日常聊天常用 relief 或直接说 things got easier。','poverty alleviation；the alleviation of suffering。','alleviation 不等于 eradication“根除”：前者允许问题仍然存在，只是程度减轻。',('The programme focuses on poverty alleviation in rural areas.','这个项目着重缓解农村地区的贫困。'),('They measured the alleviation of discomfort after the adjustment.','他们测量了调整之后不适减轻的程度。'),sources=['https://www.etymonline.com/word/alleviation','https://en.wiktionary.org/wiki/alleviation']),
E('relevant','/ˈreləvənt/','相关的；切题的；适用的','这条信息能帮我们处理眼前这件事，不是在旁边绕远路。','来自法语 relevant，经中古拉丁 relevans 接 relevare“减轻、帮助”；语义走向有帮助、与当前事项相联。',RE,'relevant experience 是与当前工作要求相关的经验，不只是任何工作年限；a relevant example 是能说明眼前观点的例子。“帮得上眼前这件事”是好用的理解画面，但不是说任何有趣的信息都 relevant。','relevant to；relevant information；relevant experience。','related 只要有联系；relevant 更常强调这种联系对当前话题或目的有用、切题。',('Please include only experience relevant to this role.','请只写与这个职位相关的经历。'),('That detail is interesting, but it is not relevant to the question.','那个细节很有趣，但与这个问题不相干。'),sources=['https://www.etymonline.com/word/relevant']),
E('relevance','/ˈreləvəns/','相关性；切题程度；现实意义','问的不是“有没有信息”，而是“这条信息与现在要解决的事有多大关系”。','relevant 的相关名词形式，以 -ence 表性质；词尾 -ant 换成 -ence。',RE+[['英语 relevance','与当前事项有关、适用这一性质']],'the relevance of a study 说研究与某问题或现实需求的联系；question its relevance 是质疑它为什么与当前讨论有关。相关不等于重要到必须压过所有其他信息。','relevance to；of direct relevance；question the relevance of。','importance 是重要性；relevance 是对某个特定话题或目的的相关性，一件大事也可能与当前问题无关。',('The teacher explained the relevance of the example.','老师解释了这个例子为什么与当前内容相关。'),('The findings have direct relevance to classroom teaching.','这些发现与课堂教学直接相关。'),sources=['https://www.etymonline.com/word/relevance']),
E('relevancy','/ˈreləvənsi/','相关性；切题性','同样是在问“这件材料跟我们正在谈的事搭得上吗”。','relevant 的 -ancy 名词形式；与 relevance 并存。',RE+[['英语 relevancy','相关、适用这一性质的另一名词形式']],'relevancy 与 relevance 大体同义，在一些法律或技术表达里较常见。日常和一般学术写作通常更容易遇到 relevance，不必硬给两词分配完全不同的中文意思。','the relevancy of evidence；relevancy to a topic。','relevance 与 relevancy 是近义名词变体；relevancy 不是“更高一级的相关性”。',('The editor questioned the relevancy of the final paragraph.','编辑质疑最后一段与文章主题的关联。'),('The discussion focused on the relevancy of the evidence.','讨论重点是这些证据是否与所谈问题相关。'),sources=['https://www.merriam-webster.com/dictionary/relevancy']),
E('irrelevant','/ɪˈreləvənt/','无关的；不切题的','可能是真的，也可能很有趣，但对眼前这个问题没有关系。','否定 in- 在 r 前同化成 ir- + relevant。',A(RE,'英语 ir- + relevant → irrelevant','相关的 → 不相关的'),'an irrelevant remark 是跑题的评论；irrelevant information 是与当前目的无关的信息。它否定关联，不是在判信息真假，也不必是在骂信息一无是处。','irrelevant to；completely irrelevant；an irrelevant detail。','incorrect 是不正确；irrelevant 是不相关。一个正确事实仍可能完全跑题。',('His age is irrelevant to the quality of his work.','他的年龄与作品质量无关。'),('We removed several irrelevant details from the report.','我们删掉了报告里几个不相关的细节。'),sources=['https://www.etymonline.com/word/irrelevant']),
E('irrelevance','/ɪˈreləvəns/','无关性；不相干的话或事','把“与当前主题搭不上”这种性质，或具体跑题内容，作为名词说出来。','ir-“不” + relevance；也与 irrelevant 的名词形式相联。',A(RE,'英语 relevance → irrelevance','相关性 → 无关性、无关事项'),'the irrelevance of a detail 是某细节与问题无关；dismiss something as an irrelevance 是把它当成无关紧要于当前讨论的事。语气可以很坚决。','the irrelevance of；an irrelevance；dismiss as an irrelevance。','irrelevance 说与当前事情无关；triviality 说琐碎，一件琐碎的小事也可能高度相关。',('The debate revealed the irrelevance of the old rule to modern practice.','这场讨论显示了旧规则与现代做法已不相适应。'),('She dismissed the personal remark as an irrelevance.','她把那句针对个人的话视为跑题之言，没有理会。')),
]
